const s=$getWorkflowStaticData('global');
s.seen=s.seen||{};
const now=Date.now();
const DAY=86400000;
const trustedOfficial=['binance','okx','coinbase','kraken'];
const trustedQuest=['galxe','layer3','zealy'];
const trustedNews=['coindesk','decrypt','the block','theblock'];
const oppWords=['airdrop','giveaway','launchpool','launchpad','learn-to-earn','learn and earn','quest','testnet','reward','campaign','claim'];
const scamWords=['seed phrase','recovery phrase','private key','send funds first','double your','guaranteed profit','whatsapp support','telegram support','remote access','screen share'];
const out=[];
for(const item of $input.all()){
  const x=item.json||{};
  const title=String(x.title||'').trim();
  const link=String(x.link||'').trim();
  const body=[title,x.content,x.contentSnippet,x.creator,x.author,x.isoDate,x.pubDate].filter(Boolean).join(' ').toLowerCase();
  if(!title||!link) continue;
  const key=(link||title).toLowerCase();
  if(s.seen[key]) continue;
  let published=Date.parse(x.isoDate||x.pubDate||'');
  if(Number.isFinite(published)&&now-published>7*DAY) continue;
  let score=35;
  let source='Discovery';
  if(trustedOfficial.some(v=>body.includes(v))){score+=40;source='Official exchange';}
  else if(trustedQuest.some(v=>body.includes(v))){score+=35;source='Quest platform';}
  else if(trustedNews.some(v=>body.includes(v))){score+=22;source='Reputable crypto news';}
  if(oppWords.some(v=>body.includes(v))) score+=15;
  if(/free|no cost|zero cost|learn/.test(body)) score+=5;
  if(/deadline|ends|until|claim|eligible/.test(body)) score+=3;
  if(/connect wallet|wallet connection/.test(body)) score-=5;
  const scamHit=scamWords.find(v=>body.includes(v));
  if(scamHit) score-=80;
  if(/send .*crypto|deposit .*to claim|pay .*fee .*claim/.test(body)) score-=45;
  score=Math.max(0,Math.min(100,score));
  s.seen[key]=now;
  if(score<80) continue;
  let cost=/free|no cost|zero cost|learn/.test(body)?'€0 indicated / verify':'Unknown — verify before action';
  let effort=/learn|quiz/.test(body)?'5–20 min':(/quest|campaign|testnet/.test(body)?'10–60+ min':'Check details');
  let risk=score>=90?'LOW':score>=80?'MEDIUM-LOW':'MEDIUM';
  out.push({json:{title,link,score,source,risk,cost,effort,deadline:'Check official page',published:x.isoDate||x.pubDate||null,action:'Review only. Do not sign or transfer until verified.'}});
}
for(const [k,v] of Object.entries(s.seen)){if(now-Number(v)>30*DAY)delete s.seen[k];}
out.sort((a,b)=>b.json.score-a.json.score);
const top=out.slice(0,5);
s.lastRunAt=new Date().toISOString();
s.lastAlerts=top.map(i=>i.json);
return top;

